/**
 * The twins against Postgres' own functions. The fixture is generated by api/scripts/privatereaders/gen_golden.py from the
 * latest drizzle definitions over synthetic rows (no live data); this test encodes those rows the way ranking-indexer's
 * mirrors write them, decodes them as the twin reads a scan, and compares every output.
 */
import {readFileSync} from "node:fs"
import {join} from "node:path"
import {describe, expect, it} from "vitest"
import type {DerivedScanRow} from "../derived"
import {
	type Contribution,
	close,
	decodeNeighbours,
	decodeSeen,
	decodeSignals,
	feedUserSeen,
	groupHex,
	KIND_BY_TAG,
	type Neighbour,
	ownTopicWeights,
	type SignalWeights,
	seenPageComplete,
	userTopicContributions,
	userTopicInterestReasons,
	userTopicWeights,
} from "../privateReaders"

type PgSignal = {
	user_id: string
	topic_id: string
	kind: string
	decayed_count: number
	event_count: number
	last_event_us: number | null
	top_object_id: string
	computed_us: number
}
type PgCooc = {topic_id: string; neighbour_id: string; similarity: number; support: number}
type PgSeen = {user_id: string; day: string; item_id: string; impressions: number; last_seen_us: number}
type Row = Record<string, string | number | null>
type Seed = {
	seed: number
	config: {half_life_days: number; spread_fraction: number}
	weights: {kind: string; weight: number; decays: boolean}[]
	maxTopics: number
	users: string[]
	sinces: string[]
	signals: PgSignal[]
	cooccurrence: PgCooc[]
	seen: PgSeen[]
	results: Record<string, Row[]>
}

const golden = JSON.parse(readFileSync(join(__dirname, "fixtures", "golden-private-readers.json"), "utf8")) as {
	asOf: string
	seeds: Seed[]
}
const asOf = new Date(golden.asOf)

const hex = (uuid: string) => groupHex(uuid)
const i32le = (n: number) => {
	const b = Buffer.alloc(4)
	b.writeInt32LE(n)
	return b.toString("hex")
}
const i64le = (n: bigint) => {
	const b = Buffer.alloc(8)
	b.writeBigInt64LE(n)
	return b.toString("hex")
}

/** user_topic_signals_mirror.rs `plan`. */
function signalRow(s: PgSignal): DerivedScanRow {
	return {
		score: s.decayed_count,
		keyHex:
			hex(s.user_id) +
			hex(s.topic_id) +
			KIND_BY_TAG.indexOf(s.kind as never)
				.toString(16)
				.padStart(2, "0"),
		valueHex:
			i32le(s.event_count) +
			i64le(s.last_event_us === null ? -(2n ** 63n) : BigInt(s.last_event_us)) +
			hex(s.top_object_id) +
			i64le(BigInt(s.computed_us)),
	}
}

/** topic_cooccurrence_mirror.rs. */
const coocRow = (c: PgCooc): DerivedScanRow => ({
	score: c.similarity,
	keyHex: hex(c.topic_id) + hex(c.neighbour_id),
	valueHex: i32le(c.support),
})

/** feed_user_seen_mirror.rs. */
function seenRow(r: PgSeen): DerivedScanRow {
	const day = Buffer.alloc(4)
	day.writeInt32BE(Math.floor(Date.parse(`${r.day}T00:00:00Z`) / 86400000))
	return {
		score: r.last_seen_us / 1e6,
		keyHex: hex(r.user_id) + day.toString("hex") + hex(r.item_id),
		valueHex: i32le(r.impressions) + i64le(BigInt(r.last_seen_us)),
	}
}

/** A scan's order: score DESC, key ASC. */
const scanOrder = (rows: DerivedScanRow[]) =>
	[...rows].sort((a, b) => b.score - a.score || (a.keyHex < b.keyHex ? -1 : a.keyHex > b.keyHex ? 1 : 0))

function twinInputs(s: Seed, user: string) {
	const signals = decodeSignals(user, scanOrder(s.signals.filter((r) => r.user_id === user).map(signalRow)))
	const weights: SignalWeights = new Map(s.weights.map((w) => [w.kind, {weight: w.weight, decays: w.decays}]))
	const config = {halfLifeDays: s.config.half_life_days, spreadFraction: s.config.spread_fraction}
	const neighbours = new Map<string, Neighbour[]>()
	for (const t of new Set(signals.map((x) => x.topicId)))
		neighbours.set(t, decodeNeighbours(t, scanOrder(s.cooccurrence.filter((c) => c.topic_id === t).map(coocRow))))
	return {contributions: userTopicContributions(signals, config, weights, neighbours, asOf)}
}

const num = (v: unknown) => (v === null || v === undefined ? null : Number(v))
const str = (v: unknown) => (v === null || v === undefined ? null : String(v))

function expectContribution(got: Contribution, want: Row, topicId: string | null) {
	if (topicId !== null) expect(got.topicId).toBe(topicId)
	expect(got.kind).toBe(want.kind)
	expect(close(got.contribution, Number(want.contribution))).toBe(true)
	expect(got.eventCount).toBe(num(want.event_count))
	expect(got.lastEventUs).toBe(num(want.last_event_us))
	expect(got.topObjectId).toBe(str(want.top_object_id))
	expect(got.viaTopicId).toBe(str(want.via_topic_id))
}

const byContributionKey = (a: Contribution, b: Contribution) =>
	`${a.topicId}|${a.kind}|${a.viaTopicId ?? "~"}` < `${b.topicId}|${b.kind}|${b.viaTopicId ?? "~"}` ? -1 : 1

describe.each(golden.seeds.map((s) => [s.seed, s] as const))("seed %i", (_, s) => {
	it.each(s.users)("user_topic_contributions %s", (user) => {
		const {contributions} = twinInputs(s, user)
		const want = s.results[`contributions:${user}`] as Row[]
		expect(contributions.length).toBe(want.length)
		// The SQL query sorted by topic, kind, via (nulls last); the same order here.
		const got = [...contributions].sort(byContributionKey)
		got.forEach((g, i) => expectContribution(g, want[i] as Row, str((want[i] as Row).topic_id)))
	})

	it.each(s.users)("user_topic_weights and readOwnWeights %s", (user) => {
		const rows = userTopicWeights(twinInputs(s, user).contributions, s.maxTopics)
		const want = s.results[`weights:${user}`] as Row[]
		expect(rows.map((r) => r.topicId)).toEqual(want.map((w) => w.topic_id))
		rows.forEach((r, i) => {
			const w = want[i] as Row
			expect(close(r.weight, Number(w.weight))).toBe(true)
			expect(close(r.ownWeight, Number(w.own_weight))).toBe(true)
			expect(close(r.relatedWeight, Number(w.related_weight))).toBe(true)
			expect(r.topKind).toBe(w.top_kind)
			expect(r.topKindCount).toBe(num(w.top_kind_count))
			expect(r.topObjectId).toBe(str(w.top_object_id))
			expect(r.relatedViaTopicId).toBe(str(w.related_via_topic_id))
		})
		const own = ownTopicWeights(rows)
		const wantOwn = want.filter((w) => Number(w.own_weight) > 0)
		expect(own.map((o) => o.topicId)).toEqual(wantOwn.map((w) => w.topic_id))
		own.forEach((o, i) => expect(close(o.weight, Number((wantOwn[i] as Row).own_weight))).toBe(true))
	})

	it.each(s.users)("user_topic_interest_reasons %s", (user) => {
		const {contributions} = twinInputs(s, user)
		for (const key of Object.keys(s.results).filter((k) => k.startsWith(`reasons:${user}:`))) {
			const topicId = key.slice(`reasons:${user}:`.length)
			const want = s.results[key] as Row[]
			const got = userTopicInterestReasons(contributions, topicId)
			expect(got.length).toBe(want.length)
			got.forEach((g, i) => expectContribution(g, want[i] as Row, topicId))
		}
	})

	it.each(s.users)("feed_user_seen %s", (user) => {
		const scan = scanOrder(s.seen.filter((r) => r.user_id === user).map(seenRow))
		const rows = decodeSeen(user, scan)
		for (const since of s.sinces) {
			const want = (s.results[`seen:${user}:${since}`] as Row[])
				.map((w) => ({
					itemId: String(w.item_id),
					seenCount: Number(w.seen_count),
					lastSeenUs: Number(w.last_seen_us),
				}))
				.sort((a, b) => b.lastSeenUs - a.lastSeenUs || (a.itemId < b.itemId ? -1 : 1))
			expect(feedUserSeen(rows, new Date(since))).toEqual(want)
			expect(seenPageComplete({rows: scan, more: false}, new Date(since))).toBe(true)
		}
	})
})

describe("coverage of the grid", () => {
	const all = golden.seeds.flatMap((s) => Object.entries(s.results))
	it("holds the cases the twin's tie-breaks and filters exist for", () => {
		const weights = all.filter(([k]) => k.startsWith("weights:")).flatMap(([, v]) => v)
		expect(weights.some((w) => w.top_kind === "related")).toBe(true)
		expect(weights.some((w) => w.related_via_topic_id !== null)).toBe(true)
		const contributions = all.filter(([k]) => k.startsWith("contributions:")).flatMap(([, v]) => v)
		expect(contributions.some((c) => Number(c.contribution) < 0)).toBe(true)
		expect(golden.seeds.some((s) => s.config.spread_fraction === 0)).toBe(true)
		expect(golden.seeds.some((s) => s.results[`weights:${s.users[1]}`]?.length === s.maxTopics)).toBe(true)
		expect(all.filter(([k]) => k.startsWith("seen:")).some(([, v]) => v.length > 0)).toBe(true)
	})
})

describe("seenPageComplete", () => {
	const since = new Date("2026-11-03T05:00:00Z")
	const dayStart = Date.parse("2026-11-03T00:00:00Z") / 1000
	const row = (score: number): DerivedScanRow => ({score, keyHex: "", valueHex: ""})
	it("is complete without more, or once a full page reaches a row before since's day", () => {
		expect(seenPageComplete({rows: [], more: false}, since)).toBe(true)
		expect(seenPageComplete({rows: [row(dayStart + 10), row(dayStart - 1)], more: true}, since)).toBe(true)
	})
	it("is truncated when a full page ends inside the window", () => {
		expect(seenPageComplete({rows: [row(dayStart + 10), row(dayStart)], more: true}, since)).toBe(false)
	})
})
